// Independent external peaks/fits and a separately identified mathematical Theil
// oracle. No expected value is generated by the native Swift implementation.
import Foundation
import Testing

@testable import HDXLVoiceProcessing

private struct CPPReference: Decodable {
    struct Frame: Decodable {
        let sampleRate: Int
        let pitchFloorHz: Double
    }
    struct Policy: Decodable {
        let cppDBAbsolute, peakDBAbsolute, quefrencySecondsAbsolute: Double
        let interceptDBAbsolute, slopeDBPerSecondAbsolute, residualDBAbsolute: Double
    }
    struct Settings: Decodable {
        let name: String
        let pitchFloorHz, pitchCeilingHz, fitStartSeconds, fitEndSeconds: Double
        let interpolation: CPPPeakInterpolation
        let fitMethod: CPPFitMethod
        func configuration() throws -> CPPConfiguration {
            try CPPConfiguration(
                pitchFloorHz: pitchFloorHz, pitchCeilingHz: pitchCeilingHz,
                interpolation: interpolation, fitStartSeconds: fitStartSeconds,
                fitEndSeconds: fitEndSeconds, fitMethod: fitMethod)
        }
    }
    struct Fit: Decodable {
        let domainStartSeconds, domainEndSeconds: Double
        let firstBin, lastBin, binCount: Int
    }
    struct Expected: Decodable {
        struct Residuals: Decodable { let rmsDB, meanDB, medianDB, maximumAbsoluteDB: Double }
        let slopeDBPerSecond, interceptDB, cppDB, peakDB, peakQuefrencySeconds, backgroundDB: Double
        let residuals: Residuals
    }
    struct Row: Decodable {
        let profile: Settings
        let effectiveFit: Fit
        let expected: Expected
        let referenceCompatible, knownReferenceException: Bool
        let expectedFitSource: String
    }
    let name: String
    let calibrationOnly: Bool
    let binCount: Int
    let quefrencyStepSeconds: Double
    let frameConfiguration: Frame
    let power: [Double?]
    let upstreamUnavailable: Bool
    let comparisonPolicy: Policy
    let results: [Row]
}

// Whole PCM processing introduces conditioning and FFT rounding before the dB
// fit. These absolute budgets are frozen separately from the same-input kernel
// budgets: 0.0001 dB, 0.01 dB/s, and 10 ns of quefrency. They are numerical
// acceptance limits for these ordinary speech frames, not clinical tolerances
// or a guarantee for ill-conditioned synthetic spectra with deep minima.
private struct CPPPCMReference: Decodable {
    struct Recipe: Decodable {
        struct Source: Decodable { let path: String }
        let name: String
        let source: Source
        let pitchFloorHz, hopSeconds, maximumFrequencyHz, preEmphasisFromHz: Double
    }
    struct Input: Decodable { let sampleRate, sampleCount: Int }
    struct Frame: Decodable {
        let index: Int
        let comparisonClass: String
    }
    let recipe: Recipe
    let input: Input
    let frames: [Frame]
    enum CodingKeys: String, CodingKey {
        case recipe = "case"
        case input, frames
    }
}

@Test func cppWholePCMExternalSpeechReferences() throws {
    let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        .deletingLastPathComponent().deletingLastPathComponent()
    let upstreamDirectory = try #require(
        Bundle.module.url(
            forResource: "Cepstrum", withExtension: nil, subdirectory: "Fixtures"))
    let env = ProcessInfo.processInfo.environment
    let cppDirectory =
        try env["HDXL_CPP_REFERENCE_DIRECTORY"].map { URL(fileURLWithPath: $0) }
        ?? #require(
            Bundle.module.url(forResource: "CPP", withExtension: nil, subdirectory: "Fixtures"))
    let files = try FileManager.default.contentsOfDirectory(
        at: upstreamDirectory, includingPropertiesForKeys: nil
    )
    .filter { $0.lastPathComponent.hasPrefix("speech-") && $0.pathExtension == "json" }
    .sorted { $0.lastPathComponent < $1.lastPathComponent }
    #expect(files.count == 8)
    var reports: [[String: Any]] = []
    for file in files {
        let fixture = try JSONDecoder().decode(CPPPCMReference.self, from: Data(contentsOf: file))
        let recipe = fixture.recipe
        let samples = try CorpusPCM(
            data: Data(contentsOf: root.appending(path: recipe.source.path))
        ).samples
        #expect(samples.count == fixture.input.sampleCount)
        let configuration = try CepstrogramConfiguration(
            sourceSampleRate: fixture.input.sampleRate,
            analysisSampleRate: Int(2 * recipe.maximumFrequencyHz), inputPrecision: .float64,
            pitchFloorHz: recipe.pitchFloorHz, hopSeconds: recipe.hopSeconds,
            preEmphasisFromHz: recipe.preEmphasisFromHz,
            declaredInputBandwidthHz: Double(fixture.input.sampleRate) / 2)
        let source = try SourceInterval(
            epoch: StreamEpoch(streamID: UUID()), startSample: 0,
            sampleCount: Int64(samples.count), sampleRate: Double(fixture.input.sampleRate))
        let upstream = try PreparedIntervalCepstrogram<Double>(
            configuration: configuration, source: source)
        let cpp = try PreparedCPP(
            CPPProfile(
                cepstrogram: configuration,
                settings: CPPConfiguration.murtonRecipePraat7()))
        var expected: [UInt64: CPPReference.Expected] = [:]
        for frame in fixture.frames {
            #expect(frame.comparisonClass == "ordinary")
            let reference = try JSONDecoder().decode(
                CPPReference.self,
                from: Data(
                    contentsOf:
                        cppDirectory.appending(path: "\(recipe.name)-frame-\(frame.index).json")))
            expected[UInt64(frame.index)] = try #require(
                reference.results.first {
                    $0.profile.name == "murton-recipe-praat7-unsmoothed"
                }
            ).expected
        }
        try samples.withUnsafeBufferPointer { try upstream.append($0, interval: source) }
        var compared: Set<UInt64> = []
        var failure: (any Error)?
        try upstream.finish { frame in
            guard let e = expected[frame.context.frameIndex], failure == nil else { return }
            do {
                try cpp.analyze(frame) { output in
                    guard let a = output.result.observation else {
                        Issue.record("Missing whole-PCM CPP observation")
                        return
                    }
                    #expect(output.result.context.timing.source == source)
                    let values: [(String, Double, Double, Double)] = [
                        ("cpp", a.prominenceDB, e.cppDB, 1e-4),
                        ("peak", a.peakDB, e.peakDB, 1e-4),
                        ("background", a.backgroundDB, e.backgroundDB, 1e-4),
                        ("intercept", a.interceptDB, e.interceptDB, 1e-4),
                        ("slope", a.slopeDBPerSecond, e.slopeDBPerSecond, 0.01),
                        ("quefrency", a.peakQuefrencySeconds, e.peakQuefrencySeconds, 1e-8),
                        ("residualMean", a.residualMeanDB, e.residuals.meanDB, 1e-4),
                        ("residualRMS", a.residualRMSDB, e.residuals.rmsDB, 1e-4),
                        ("residualMedian", a.residualMedianDB, e.residuals.medianDB, 1e-4),
                        (
                            "residualMaximum", a.residualMaximumAbsoluteDB,
                            e.residuals.maximumAbsoluteDB, 1e-4
                        ),
                    ]
                    var differences: [String: Double] = [:]
                    var maximumFraction = 0.0
                    for (name, actual, reference, budget) in values {
                        let delta = abs(actual - reference)
                        differences[name] = delta
                        maximumFraction = max(maximumFraction, delta / budget)
                        #expect(
                            delta <= budget,
                            "\(recipe.name)/\(frame.context.frameIndex)/\(name): \(delta) > \(budget)"
                        )
                    }
                    reports.append([
                        "case": recipe.name, "frame": frame.context.frameIndex,
                        "maximumBudgetFraction": maximumFraction,
                        "absoluteDifferences": differences,
                    ])
                    #expect(compared.insert(frame.context.frameIndex).inserted)
                }
            } catch { failure = error }
        }
        if let failure { throw failure }
        #expect(compared == Set(expected.keys))
    }
    #expect(reports.count == 40)
    if let path = env["HDXL_CPP_PCM_REFERENCE_REPORT"] {
        try JSONSerialization.data(withJSONObject: reports, options: [.sortedKeys, .prettyPrinted])
            .write(to: URL(fileURLWithPath: path), options: .atomic)
    }
}

@Test func cppExternalReferences() throws {
    let env = ProcessInfo.processInfo.environment
    let directory =
        try env["HDXL_CPP_REFERENCE_DIRECTORY"].map { URL(fileURLWithPath: $0) }
        ?? #require(
            Bundle.module.url(forResource: "CPP", withExtension: nil, subdirectory: "Fixtures"))
    let files = try FileManager.default.contentsOfDirectory(
        at: directory, includingPropertiesForKeys: nil
    )
    .filter { $0.pathExtension == "json" && $0.lastPathComponent != "manifest.json" }
    .sorted { $0.lastPathComponent < $1.lastPathComponent }
    #expect(files.count == 216)
    var reports: [[String: Any]] = []
    var unavailable = 0
    var exceptions = 0
    for file in files {
        let fixture = try JSONDecoder().decode(CPPReference.self, from: Data(contentsOf: file))
        #expect(!fixture.calibrationOnly)
        let frame = try PowerCepstrumConfiguration(
            sampleRate: fixture.frameConfiguration.sampleRate,
            pitchFloorHz: fixture.frameConfiguration.pitchFloorHz)
        #expect(frame.binCount == fixture.binCount)
        #expect(frame.quefrencyStepSeconds == fixture.quefrencyStepSeconds)
        let context = try cepstrumContext(count: frame.frameLength, rate: frame.sampleRate)
        if fixture.upstreamUnavailable {
            unavailable += 1
            #expect(fixture.power.allSatisfy { $0 == nil } && fixture.results.isEmpty)
            continue
        }
        let power = try fixture.power.map { try #require($0) }
        #expect(fixture.results.count == 7)
        for row in fixture.results {
            let worker = try PreparedCPP(
                CPPProfile(frame: frame, settings: row.profile.configuration()))
            let l = worker.layout
            let fit = row.effectiveFit
            #expect(
                l.firstFitBin == fit.firstBin && l.lastFitBin == fit.lastBin
                    && l.fitPointCount == fit.binCount)
            #expect(
                l.fitStartSeconds == fit.domainStartSeconds
                    && l.fitEndSeconds == fit.domainEndSeconds)
            if row.knownReferenceException { exceptions += 1 }
            #expect(row.referenceCompatible != row.knownReferenceException)
            #expect(
                row.expectedFitSource
                    == (row.profile.fitMethod == .completeTheilSen
                        ? "independent-complete-pairwise-median" : "pinned-praat-query"))
            var observations = 0
            try power.withUnsafeBufferPointer { input in
                try worker.analyzePowerCepstrum(input, context: context) { output in
                    observations += 1
                    guard let actual = output.result.observation else {
                        Issue.record("Missing \(fixture.name)/\(row.profile.name)")
                        return
                    }
                    let expected = row.expected
                    let policy = fixture.comparisonPolicy
                    let values: [(String, Double, Double, Double)] = [
                        ("cpp", actual.prominenceDB, expected.cppDB, policy.cppDBAbsolute),
                        ("peak", actual.peakDB, expected.peakDB, policy.peakDBAbsolute),
                        (
                            "quefrency", actual.peakQuefrencySeconds, expected.peakQuefrencySeconds,
                            policy.quefrencySecondsAbsolute
                        ),
                        (
                            "slope", actual.slopeDBPerSecond, expected.slopeDBPerSecond,
                            policy.slopeDBPerSecondAbsolute
                        ),
                        (
                            "intercept", actual.interceptDB, expected.interceptDB,
                            policy.interceptDBAbsolute
                        ),
                        (
                            "background", actual.backgroundDB, expected.backgroundDB,
                            policy.cppDBAbsolute
                        ),
                        (
                            "residualMean", actual.residualMeanDB, expected.residuals.meanDB,
                            policy.residualDBAbsolute
                        ),
                        (
                            "residualRMS", actual.residualRMSDB, expected.residuals.rmsDB,
                            policy.residualDBAbsolute
                        ),
                        (
                            "residualMedian", actual.residualMedianDB, expected.residuals.medianDB,
                            policy.residualDBAbsolute
                        ),
                        (
                            "residualMaximum", actual.residualMaximumAbsoluteDB,
                            expected.residuals.maximumAbsoluteDB, policy.residualDBAbsolute
                        ),
                    ]
                    var maximumFraction = 0.0
                    for (field, value, expected, tolerance) in values {
                        let fraction = abs(value - expected) / tolerance
                        maximumFraction = max(maximumFraction, fraction)
                        #expect(
                            fraction <= 1,
                            "\(fixture.name)/\(row.profile.name)/\(field): \(value) vs \(expected)")
                    }
                    let dB = output.values(.cepstralDB)
                    let background = output.values(.backgroundDB)
                    let residual = output.values(.residualDB)
                    #expect(
                        dB.count == power.count && background.count == power.count
                            && residual.count == power.count)
                    for i in power.indices {
                        #expect(abs(dB[i] - 10 * log10(power[i] + 1e-30)) < 1e-11)
                        #expect(
                            abs(
                                background[i]
                                    - (actual.slopeDBPerSecond * Double(i) * l.quefrencyStepSeconds
                                        + actual.interceptDB)) < 1e-9)
                        #expect(abs(residual[i] - (dB[i] - background[i])) < 1e-11)
                    }
                    reports.append([
                        "case": fixture.name, "profile": row.profile.name,
                        "referenceCompatible": row.referenceCompatible,
                        "maximumBudgetFraction": maximumFraction,
                        "cppAbsoluteDifference": abs(actual.prominenceDB - expected.cppDB),
                    ])
                }
            }
            #expect(observations == 1)
        }
    }
    #expect(unavailable == 14 && exceptions == 32 && reports.count == 1414)
    if let path = env["HDXL_CPP_REFERENCE_REPORT"] {
        let report: [String: Any] = [
            "schemaVersion": 1, "cases": files.count,
            "upstreamUnavailable": unavailable, "knownReferenceExceptions": exceptions,
            "comparisons": reports,
        ]
        try JSONSerialization.data(withJSONObject: report, options: [.sortedKeys, .prettyPrinted])
            .write(to: URL(fileURLWithPath: path), options: .atomic)
    }
}
